// ============================================================================
// BUILD REGISTRY - Extract metadata from workflows
// ============================================================================

const workflows = $input.first().json.data || [];
const baseUrl = $env.WEBHOOK_URL || 'http://pi6.local:5678/';

// Filter: active + has webhook + not TORAH/Registry
const toolWorkflows = workflows.filter(w =>
  w.active &&
  !w.name.includes('Registry') &&
  !w.name.includes('TORAH')
);

// Build tools object
const tools = {};

for (const workflow of toolWorkflows) {
  const webhookNode = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.webhook');

  if (webhookNode) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;

    // Extract description from sticky note
    const stickyNote = workflow.nodes?.find(n => n.type === 'n8n-nodes-base.stickyNote');
    const stickyContent = stickyNote?.parameters?.content || '';

    // Parse description from sticky (after "Description:")
    const descMatch = stickyContent.match(/\*\*Description[:\s]*\*\*\s*\n?([^\n*]+)/i);
    const description = descMatch ? descMatch[1].trim() : workflow.name;

    // Extract InputSchema from sticky note (JSON block after **InputSchema:**)
    let inputSchema = null;
    const schemaMatch = stickyContent.match(/\*\*InputSchema:\*\*\s*```json\s*([\s\S]*?)```/i);
    if (schemaMatch) {
      try {
        inputSchema = JSON.parse(schemaMatch[1].trim());
      } catch (e) {
        // Invalid JSON, skip
      }
    }

    // Build parameters from inputSchema
    const parameters = { required: {}, optional: {} };
    if (inputSchema?.properties) {
      const requiredFields = inputSchema.required || [];
      for (const [key, prop] of Object.entries(inputSchema.properties)) {
        const paramDef = {
          type: prop.type || 'string',
          description: prop.description || key
        };
        if (prop.default !== undefined) paramDef.default = prop.default;
        if (prop.enum) paramDef.enum = prop.enum;

        if (requiredFields.includes(key)) {
          parameters.required[key] = paramDef;
        } else {
          parameters.optional[key] = paramDef;
        }
      }
    }

    // Extract scope from settings or default to "user"
    const scope = workflow.settings?.scope || 'user';

    // Extract tags from workflow tags or name
    const tags = workflow.tags?.map(t => t.name) || [];

    tools[webhookPath] = {
      name: workflow.name,
      description: description,
      workflow_id: workflow.id,
      endpoint: `/webhook/${webhookPath}`,
      webhook_url: `${baseUrl}webhook/${webhookPath}`,
      method: webhookNode.parameters?.httpMethod || "POST",
      scope: scope,
      tags: tags,
      parameters: parameters,
      inputSchema: inputSchema,
      active: workflow.active
    };
  }
}

return {
  json: {
    version: "4.3",
    updated_at: new Date().toISOString(),
    total_tools: Object.keys(tools).length,
    tools: tools
  }
};
